    op = action.get('operation')
    if op == 'deploy':
        state['version'] = action.get('version', state['version'])
        state['phase'] = 'starting'
        state['ready'] = False
        state['promoted'] = False
        state['probe_count'] = 0
    elif op == 'probe':
        if state['phase'] == 'starting' and not state['ready']:
            state['probe_count'] += 1
            if state['probe_count'] >= 3:
                state['ready'] = True
                state['phase'] = 'ready'
    elif op == 'promote':
        if state['phase'] == 'ready':
            state['phase'] = 'active'
            state['promoted'] = True
        else:
            state['phase'] = 'failed'
    return state

def render(state):
    return {'version': state['version'], 'phase': state['phase']}

def outcome(state):
    if state['phase'] == 'failed':
        return 'failed'
    if state['version'] == 'v2' and state['phase'] == 'active':
        return 'complete'
    return 'ongoing'

